// TensorForge matrix-job orchestration.
// Coordinates generated by matrix_tile_iterator are held until the host
// confirms operands have been staged and the engine/writeback complete.
// This module does not perform DMA or automatically copy operand bytes.
module matrix_job_controller #(
    parameter int N = 4,
    parameter int K_TILE = 32,
    parameter int IDX_W = 16
) (
    input logic clk, rst_n,
    input logic start,
    input logic [IDX_W-1:0] m_dim, k_dim, p_dim,
    input logic operands_ready,
    input logic engine_busy, engine_done,
    input logic writeback_done,
    output logic engine_start,
    output logic waiting_for_operands,
    output logic waiting_for_engine,
    output logic waiting_for_writeback,
    output logic job_done,
    output logic [IDX_W-1:0] tile_row, tile_col, k_block,
    output logic [$clog2(K_TILE+1)-1:0] current_k_len,
    output logic first_k_block, last_k_block,
    output logic [31:0] tiles_visited
);
    typedef enum logic [2:0] {IDLE, PREPARE, LAUNCH, COMPUTE, WRITEBACK, ADVANCE} state_t;
    state_t state;
    logic iterator_start, iterator_advance, iterator_active, iterator_done;
    logic engine_done_d, wb_done_d;
    assign iterator_start = start && state == IDLE;
    assign iterator_advance = state == ADVANCE;
    assign engine_start = state == LAUNCH;
    assign waiting_for_operands = state == PREPARE;
    assign waiting_for_engine = state == COMPUTE;
    assign waiting_for_writeback = state == WRITEBACK;
    assign job_done = state == IDLE && iterator_done;
    matrix_tile_iterator #(.N(N), .K_TILE(K_TILE), .IDX_W(IDX_W)) iterator (
        .clk(clk), .rst_n(rst_n), .start(iterator_start),
        .tile_advance(iterator_advance), .m_dim(m_dim),
        .k_dim(k_dim), .p_dim(p_dim),
        .active(iterator_active), .done(iterator_done),
        .tile_row(tile_row), .tile_col(tile_col), .k_block(k_block),
        .current_k_len(current_k_len),
        .first_k_block(first_k_block), .last_k_block(last_k_block),
        .tiles_visited(tiles_visited)
    );
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            state <= IDLE;
            engine_done_d <= 1'b0;
            wb_done_d <= 1'b0;
        end else begin
            engine_done_d <= engine_done;
            wb_done_d <= writeback_done;
            case (state)
                IDLE: if (start) state <= PREPARE;
                PREPARE: begin
                    if (!iterator_active) state <= IDLE;
                    else if (operands_ready) state <= LAUNCH;
                end
                LAUNCH: state <= COMPUTE;
                COMPUTE: if (engine_done && !engine_done_d) state <= WRITEBACK;
                WRITEBACK: if (writeback_done && !wb_done_d) state <= ADVANCE;
                ADVANCE: state <= PREPARE;
                default: state <= IDLE;
            endcase
        end
    end
endmodule
